customDefs.css:
* { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    width: 100%; height: 100%; overflow: hidden;
    background: transparent;
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  }

  .sandbox-container {
    position: relative; width: 100%; height: 100%;
    display: flex; justify-content: center; align-items: center;
  }
  .input-capsule {
    width: 90%; 
    max-width: 320px;
    height: 48px;
    background: rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(15px);
    -webkit-backdrop-filter: blur(15px);
    border: 1px solid rgba(120,120,120,0.45);
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 18px 0 22px;
    box-shadow: 0 8px 25px rgba(0,0,0,0.08);
  }
  .text-area {
    display: flex;
    align-items: center;
    flex: 1;
    overflow: hidden;
  }
  .typing-text {
    font-size: 14px;
    color: #222222; /*文字改成黑色*/
    font-weight: 500;
    letter-spacing: 0.5px;
    white-space: nowrap;
    text-shadow: none;
  }
  .cursor {
    display: inline-block;
    width: 2px;
    height: 16px;
    background-color: #333333; /*光标改为深灰*/
    margin-left: 4px;
    vertical-align: middle;
    animation: blink 1s step-end infinite;
  }
  @keyframes blink {
    0%, 100% { opacity: 1; }
    50% { opacity: 0; }
  }
  .send-icon {
    width: 20px;
    height: 20px;
    opacity: 0.4;
    transition: opacity 0.3s, transform 0.3s;
    stroke:#444444; /*图标灰色*/
  }

  .input-capsule.typing .send-icon {
    opacity: 1;
    transform: translateX(2px) translateY(-2px);
    filter: drop-shadow(0 0 4px rgba(80,80,80,0.4));
  }

  .input-capsule.sending .send-icon {
    transform: scale(0.8) translate(2px, -2px);
    opacity: 0.8;
  }

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
  }
  html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: transparent;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "PingFang SC", sans-serif;
  }
  .clock-widget {
    width: 100%;
    height: 100%;
    position: relative;
    background: transparent;
    border-radius: 12px;
    padding: 14px 18px;
    overflow: hidden;
  }
  .top-left {
    position: absolute;
    top: 12px;
    left: 16px;
    display: flex;
    flex-direction: column;
    gap: 2px;
    color: #9a9a9a;
  }
  .date-text, .week-text {
    font-size: 11px;
    letter-spacing: 0.5px;
  }
  .center-area {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    transform: translateY(20px);
    gap: 12px;
  }
  .time-text {
    font-family: "Great Vibes", "Brush Script MT", "Allura", "Dancing Script", cursive;
    font-size: 46px;
    font-weight: 400;
    color: #000000;
    letter-spacing: 2px;
    line-height: 1;
    font-variant-numeric: tabular-nums;
  }
  .edit-text {
    max-width: 90%;
    font-size: 12px;
    color: #333333;
    text-align: center;
    line-height: 1.6;
    cursor: pointer;
    user-select: none;
  }
  .edit-text:active { opacity: 0.6; }

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    -webkit-tap-highlight-color: transparent;
  }
  html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: transparent;
    font-family: system-ui, sans-serif;
  }
  .widget {
    width: 100%;
    height: 100%;
    background: transparent;
    padding: 8px 10px;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
  }
  /* 大竖向照片框：不再正方形，要大 */
  .photo-box {
    width: 82px;
    height: 110px;
    flex-shrink: 0;
    position: relative;
    cursor: pointer;
    margin-left: 4px;
    border-radius: 16px;
    overflow: hidden;
    background: #f3f4f6;
    box-shadow:
      inset 0 0 0 2px rgba(255,255,255,0.9),
      0 10px 22px rgba(0, 0, 0, 0.2);
  }
  .photo-box img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }
  .photo-tip {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #555;
    font-size: 12px;
    letter-spacing: 1px;
    background:
      repeating-linear-gradient(0deg, rgba(0,0,0,0.05) 0 1px, transparent 1px 4px);
  }
  #file-input {
    display: none;
  }
  .text-box {
    flex: 1;
    border: 1px solid #cfd9e8;
    border-radius: 12px;
    padding: 3px 10px;
    background: rgba(255,255,255,0.6);
  }
  .text-area {
    display: flex;
    flex-direction: column;
    justify-content: center;
  }
  .text-item {
    width: 100%;
    padding: 6px 0;
    border-bottom: 1px solid #cfd9e8;
  }
  .text-item:last-child {
    border-bottom: none;
  }
  .edit-text {
    display: block;
    width: 100%;
    font-size: 14px;
    color: #111;
    line-height: 20px;
    cursor: pointer;
  }

* {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
      -webkit-tap-highlight-color: transparent;
    }
    html, body {
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: transparent;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    }
    .polaroid-widget {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
      padding: 6px;
    }
    .polaroid-strip {
      display: flex;
      flex-direction: row;
      align-items: center;
      justify-content: center;
      gap: 4px;
      width: 100%;
      height: 100%;
    }
    /* 拍立得单格 把底部padding归零 */
    .polaroid {
      flex: 1;
      height: 100%;
      background: #ffffff;
      border-radius: 4px;
      padding: 5px;
      box-shadow:
        0 4px 14px rgba(0, 0, 0, 0.25),
        0 0 0 1px rgba(0, 0, 0, 0.06);
      display: flex;
      flex-direction: column;
      align-items: center;
      position: relative;
      overflow: hidden;
    }
    /* 照片区域 */
    .polaroid-img-wrap {
      width: 100%;
      flex: 1;
      background: #f2f2f2;
      border-radius: 3px;
      overflow: hidden;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }
    .polaroid-img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: none;
    }
    .polaroid-placeholder {
      font-size: 11px;
      color: #999;
      text-align: center;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 4px;
      letter-spacing: 0.5px;
      user-select: none;
    }
    .polaroid-placeholder span {
      font-size: 8px;
      color: #bbb;
    }
 /* 隐藏上传按钮 */
    .file-input {
      position: absolute;
      inset: 0;
      opacity: 0;
      cursor: pointer;
      z-index: 5;
    }

.box{
  width:100%;
  height:100%;
  display:flex;
  align-items:center;
  gap:10px;
  padding:0 10px;
}
.avatar{
  width:48px;
  height:48px;
  border-radius:999px;
  object-fit:cover;
  flex:0 0 auto;
  cursor:pointer;
}
#file{
  display:none;
}
.txt-group{
  display:flex;
  flex-direction:column;
  gap:6px;
}
.box-name{
  width: fit-content;
  padding: 3px 7px;
  border: 1px solid #ccc;
  border-radius: 5px;
  font-size:12px;
  color:#000;
}
.box-text{
  padding: 6px 8px;
  border: 1px solid #ccc;
  border-radius: 5px;
  font-size:12px;
  color:#000;
  line-height: 1.45;
}

.music-card{
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  box-sizing: border-box;
  background: transparent;
  border-radius: 14px;
}
.cover-wrap{
  flex: 0 0 64px;
}
.cover{
  width: 64px;
  height: 64px;
  border-radius: 12px;
  object-fit: cover;
  cursor: pointer;
  display:block;
  background: #eee;
}
#imgInput{
  display: none;
}
.text-area{
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}
.label-top{
  font-size: 12px;
  color:#b8b8b8;
  line-height: 1;
}
.song-name{
  font-size: 18px;
  font-style: italic;
  font-family: serif;
  color:#222;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}
.progress-bar{
  width: 100%;
  height: 5px;
  background: #e9e9e9;
  border-radius: 999px;
  margin-top: 6px;
}
.progress-fill{
  width: 52%;
  height: 100%;
  background: #b8b8b8;
  border-radius: inherit;
}

